INSERT INTO knowledge_article (title, category, status, body) VALUES
('Refunds for unused data add-ons', 'BILLING', 'PUBLISHED', 'An unused data add-on can be refunded within 14 days of purchase. The refund goes back to the original payment method within 5 business days. Add-ons that have been partly used are not refundable.'),
('Reset a blocked SIM PIN', 'DEVICES', 'PUBLISHED', 'Enter the PUK code printed on your SIM card packaging to unblock a locked SIM. After 10 wrong PUK attempts the SIM is permanently blocked and must be replaced in a store.'),
('Roaming in Europe', 'ROAMING', 'PUBLISHED', 'Your plan includes roaming in 30 listed European countries at no extra charge, up to a fair-use limit of 12 GB per month. Data beyond the limit is billed at the standard add-on rate.'),
('Change your payment method', 'BILLING', 'PUBLISHED', 'Open Account, then Billing, then Payment methods and choose Edit. A new card becomes active immediately and is used for the next invoice.'),
('Transfer your number to Brightwave', 'ACCOUNT', 'PUBLISHED', 'Number transfers normally complete within one working day. Keep your old SIM active until the transfer confirmation message arrives.'),
('5G Home Internet pricing', 'PLANS', 'DRAFT', 'DRAFT: 5G Home Internet will cost 40 per month with unlimited data. Pricing is not final and must not be shared with customers.');
